// Read the Email Ingestion Agent result
const ingestionRaw = $('Email Ingestion Agent').first().json;

// Read the incoming Lead Qualifier result
const qualifierRaw = $json;

/**
 * Converts:
 * 1. A normal JSON object -> same object
 * 2. { output: "{...}" } -> parsed object
 * 3. A JSON string -> parsed object
 */
function parseAgentOutput(data) {
  // If the entire value is a JSON string, parse it.
  if (typeof data === 'string') {
    try {
      return JSON.parse(data);
    } catch (error) {
      return {};
    }
  }

  // If n8n/AI Agent stores the actual result inside output as a JSON string.
  if (data?.output && typeof data.output === 'string') {
    try {
      return JSON.parse(data.output);
    } catch (error) {
      return data;
    }
  }

  // If output is already an object.
  if (data?.output && typeof data.output === 'object') {
    return data.output;
  }

  // Standard object output.
  return data || {};
}

const ingestion = parseAgentOutput(ingestionRaw);
const qualifier = parseAgentOutput(qualifierRaw);

// Return one clean, flat lead record.
return {
  json: {
    lead_id: ingestion.lead_id || null,
    customer_name: ingestion.customer_name || null,
    email: ingestion.email || null,
    company: ingestion.company || null,
    product_interest: ingestion.product_interest || null,
    budget: ingestion.budget ?? null,
    urgency: ingestion.urgency ?? null,
    source: ingestion.source || 'Email',
    date_received: ingestion.date_received ?? null,
    status: ingestion.status || null,
    assigned_to: ingestion.assigned_to ?? null,
    notes: ingestion.notes || null,

    // This comes from Lead Qualifier Agent.
    classification: qualifier.classification || null,
  },
};

function randomHex(length) {
  const chars = '0123456789abcdef';
  let value = '';

  for (let i = 0; i < length; i++) {
    value += chars[Math.floor(Math.random() * chars.length)];
  }

  return value;
}

const rawEmail = $json.Email || $json.raw_email || '';

return {
  json: {
    ...$json,
    trace_context: {
      // One trace ID for the entire processing journey of ONE email.
      trace_id: randomHex(32),

      // The workflow/root span.
      root_span_id: randomHex(16),

      workflow_run_id: `sg-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      trace_name: 'salesgenie.email.process',
      environment: 'development',
      workflow_version: 'phase-2-v1',
      catalog_version: 'google-sheets-phase-1',
      source: 'Email',

      workflow_start_unix_nano: `${Date.now()}000000`,

      // Safe input metadata. Do not add raw email content or full email address.
      input_row_number: $json.row_number || null,
      raw_email_present: rawEmail.length > 0,
      raw_email_length: rawEmail.length,
    },
  },
};

function randomHex(length) {
  const chars = '0123456789abcdef';
  let value = '';
  for (let i = 0; i < length; i++) {
    value += chars[Math.floor(Math.random() * chars.length)];
  }
  return value;
}

// Agent output can be direct JSON or a JSON string in `output`.
let ingestion = $json.output || $json;
if (typeof ingestion === 'string') {
  try {
    ingestion = JSON.parse(ingestion);
  } catch {
    ingestion = {};
  }
}

// `.item` preserves the paired source item when the workflow runs multiple rows.
const source = $('Create SalesGenie Trace Context').item.json;
const trace = source.trace_context;
const endTimeUnixNano = `${Date.now()}000000`;

return {
  json: {
    resourceSpans: [
      {
        resource: {
          attributes: [
            { key: 'service.name', value: { stringValue: 'salesgenie-n8n' } },
            { key: 'deployment.environment.name', value: { stringValue: trace.environment } },
          ],
        },
        scopeSpans: [
          {
            scope: { name: 'salesgenie', version: '1.0.0' },
            spans: [
              {
                traceId: trace.trace_id,
                spanId: randomHex(16),
                parentSpanId: trace.root_span_id,
                name: 'email.ingestion',
                kind: 1,
                startTimeUnixNano: trace.workflow_start_unix_nano,
                endTimeUnixNano,
                attributes: [
                  { key: 'langfuse.trace.name', value: { stringValue: trace.trace_name } },
                  { key: 'langfuse.observation.type', value: { stringValue: 'generation' } },
                  { key: 'langfuse.observation.input', value: { stringValue: JSON.stringify({
                    source: 'Email',
                    raw_email_present: trace.raw_email_present,
                    raw_email_length: trace.raw_email_length,
                  }) } },
                  { key: 'langfuse.observation.output', value: { stringValue: JSON.stringify({
                    lead_id_present: Boolean(ingestion.lead_id),
                    customer_name_present: Boolean(ingestion.customer_name),
                    sender_email_present: Boolean(ingestion.email),
                    company_present: Boolean(ingestion.company),
                    product_interest: ingestion.product_interest || null,
                    budget: ingestion.budget ?? null,
                    urgency: ingestion.urgency ?? null,
                    status: ingestion.status || null,
                  }) } },
                  { key: 'salesgenie.agent.name', value: { stringValue: 'email_ingestion' } },
                  { key: 'salesgenie.prompt.version', value: { stringValue: 'ingestion-v1' } },
                ],
              },
            ],
          },
        ],
      },
    ],
  },
};

function randomHex(length) {
  const chars = '0123456789abcdef';
  let value = '';
  for (let i = 0; i < length; i++) {
    value += chars[Math.floor(Math.random() * chars.length)];
  }
  return value;
}

let qualifier = $json.output || $json;
if (typeof qualifier === 'string') {
  try {
    qualifier = JSON.parse(qualifier);
  } catch {
    qualifier = {};
  }
}

const source = $('Create SalesGenie Trace Context').item.json;
const trace = source.trace_context;
const ingestionRaw = $('Email Ingestion Agent').item.json;

let ingestion = ingestionRaw.output || ingestionRaw;
if (typeof ingestion === 'string') {
  try {
    ingestion = JSON.parse(ingestion);
  } catch {
    ingestion = {};
  }
}

const now = `${Date.now()}000000`;

return {
  json: {
    resourceSpans: [
      {
        resource: {
          attributes: [
            { key: 'service.name', value: { stringValue: 'salesgenie-n8n' } },
            { key: 'deployment.environment.name', value: { stringValue: trace.environment } },
          ],
        },
        scopeSpans: [
          {
            scope: { name: 'salesgenie', version: '1.0.0' },
            spans: [
              {
                traceId: trace.trace_id,
                spanId: randomHex(16),
                parentSpanId: trace.root_span_id,
                name: 'lead.qualification',
                kind: 1,
                startTimeUnixNano: trace.workflow_start_unix_nano,
                endTimeUnixNano: now,
                attributes: [
                  { key: 'langfuse.trace.name', value: { stringValue: trace.trace_name } },
                  { key: 'langfuse.observation.type', value: { stringValue: 'generation' } },
                  { key: 'langfuse.observation.input', value: { stringValue: JSON.stringify({
                    product_interest: ingestion.product_interest || null,
                    budget: ingestion.budget ?? null,
                    urgency: ingestion.urgency ?? null,
                    status: ingestion.status || null,
                    notes_present: Boolean(ingestion.notes),
                  }) } },
                  { key: 'langfuse.observation.output', value: { stringValue: JSON.stringify({
                    classification: qualifier.classification || null,
                  }) } },
                  { key: 'salesgenie.agent.name', value: { stringValue: 'lead_qualifier' } },
                  { key: 'salesgenie.prompt.version', value: { stringValue: 'qualifier-v1' } },
                ],
              },
            ],
          },
        ],
      },
    ],
  },
};

// Convert Email Ingestion Agent's JSON-string output
// into normal n8n fields before Lead Qualifier receives it.

let lead = $json.output || $json;

if (typeof lead === 'string') {
  try {
    lead = JSON.parse(lead);
  } catch (error) {
    return {
      json: {
        parsing_error: true,
        parsing_error_message: 'Email Ingestion output is not valid JSON.',
        raw_output: $json.output || null,
      },
    };
  }
}

return {
  json: {
    ...lead,
    message_type: 'sales_inquiry',
  },
};

// All 13 lead records coming from Google Sheets
const allRows = $input.all().map(item => item.json);

// Fixed sample reporting period for testing
const reportStart = new Date('2026-04-01T00:00:00.000Z');
const reportEnd = new Date('2026-04-13T23:59:59.999Z');

// Converts Google Sheets dates such as 2026-04-01 or 4/1/2026
function parseDate(value) {
  if (!value) return null;

  const text = String(value).trim();

  // YYYY-MM-DD format
  const isoMatch = text.match(/^(\d{4})-(\d{2})-(\d{2})$/);

  if (isoMatch) {
    const [, year, month, day] = isoMatch;

    return new Date(Date.UTC(
      Number(year),
      Number(month) - 1,
      Number(day),
      12, 0, 0
    ));
  }

  // M/D/YYYY or MM/DD/YYYY format
  const sheetMatch = text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);

  if (sheetMatch) {
    const [, month, day, year] = sheetMatch;

    return new Date(Date.UTC(
      Number(year),
      Number(month) - 1,
      Number(day),
      12, 0, 0
    ));
  }

  const parsed = new Date(text);

  return Number.isNaN(parsed.getTime()) ? null : parsed;
}

// Converts budget to number; Unknown becomes null
function parseBudget(value) {
  if (
    value === null ||
    value === undefined ||
    value === '' ||
    String(value).trim().toLowerCase() === 'unknown'
  ) {
    return null;
  }

  const result = Number(String(value).replace(/[$,]/g, ''));

  return Number.isFinite(result) ? result : null;
}

// Normalizes Hot/Warm/Cold values
function normalizeTier(value) {
  const tier = String(value || '').trim().toLowerCase();

  if (tier === 'hot') return 'Hot';
  if (tier === 'warm') return 'Warm';
  if (tier === 'cold') return 'Cold';

  return null;
}

// Normalizes product interests into weekly report categories
function normalizeCategory(value) {
  const product = String(value || '').toLowerCase();

  if (product.includes('full office package')) {
    return 'Full Office Package';
  }

  if (product.includes('desk')) {
    return 'Desks';
  }

  if (product.includes('chair')) {
    return 'Chairs';
  }

  if (
    product.includes('conference') ||
    product.includes('table') ||
    product.includes('huddle')
  ) {
    return 'Tables & Meeting Furniture';
  }

  if (product.includes('accessory')) {
    return 'Accessories';
  }

  if (
    product.includes('storage') ||
    product.includes('bookshelf') ||
    product.includes('filing')
  ) {
    return 'Storage';
  }

  return 'Unspecified';
}

// Normalize every Google Sheets lead row
const normalizedRows = allRows.map(row => {
  const rawTier = String(
    row.lead_tier ||
    row.classification ||
    ''
  ).trim();

  const status = String(
    row.status ||
    row.Status ||
    row['Status '] ||
    ''
  ).trim();

  const date = parseDate(
    row.processed_at ||
    row.date_received
  );

  return {
    lead_id: row.lead_id || null,
    customer_name: row.customer_name || null,
    company: row.company || null,
    raw_lead_tier: rawTier,
    lead_tier: normalizeTier(rawTier),
    product_interest: row.product_interest || null,
    reporting_category: normalizeCategory(row.product_interest),
    budget: parseBudget(row.budget),
    urgency: row.urgency || null,
    status: status || null,
    notes: row.notes || row.Notes || null,
    processed_at: date ? date.toISOString() : null,
  };
});

// Include only rows within the fixed test period
const rowsInWindow = normalizedRows.filter(lead => {
  if (!lead.processed_at) return false;

  const processedDate = new Date(lead.processed_at);

  return processedDate >= reportStart && processedDate <= reportEnd;
});

// Treat a row as spam if either status or raw tier says spam
const excludedSpam = rowsInWindow.filter(lead => {
  return (
    String(lead.status || '').toLowerCase() === 'spam' ||
    String(lead.raw_lead_tier || '').toLowerCase() === 'spam'
  );
});

const excludedSupport = rowsInWindow.filter(lead => {
  return String(lead.status || '').toLowerCase() === 'support';
});

const validSalesLeads = rowsInWindow.filter(lead => {
  const isSpam =
    String(lead.status || '').toLowerCase() === 'spam' ||
    String(lead.raw_lead_tier || '').toLowerCase() === 'spam';

  const isSupport =
    String(lead.status || '').toLowerCase() === 'support';

  return !isSpam && !isSupport;
});

// Return one weekly-data object to the metric-calculation node
return [
  {
    json: {
      report_type: 'weekly_sales_insights',

      reporting_period: {
        start_date: '2026-04-01T00:00:00.000Z',
        end_date: '2026-04-13T23:59:59.999Z',
        timezone: 'Asia/Kolkata',
      },

      generated_at: new Date().toISOString(),

      rows_read: allRows.length,
      rows_in_reporting_window: rowsInWindow.length,
      excluded_spam_count: excludedSpam.length,
      excluded_support_count: excludedSupport.length,
      valid_sales_leads: validSalesLeads,

      // Temporary debug fields: remove after confirming results
      debug_first_sheet_date: allRows[0]?.processed_at || null,
      debug_first_normalized_date: normalizedRows[0]?.processed_at || null,
    },
  },
];

const input = $input.first().json;
const leads = input.valid_sales_leads || [];

const tierCounts = {
  Hot: 0,
  Warm: 0,
  Cold: 0,
  Unclassified: 0,
};

const categoryCounts = {};
const urgencyCounts = {
  High: 0,
  Medium: 0,
  Low: 0,
  Unknown: 0,
};

const statusCounts = {};
const numericBudgets = [];

for (const lead of leads) {
  // Lead tier counts
  if (lead.lead_tier && tierCounts[lead.lead_tier] !== undefined) {
    tierCounts[lead.lead_tier] += 1;
  } else {
    tierCounts.Unclassified += 1;
  }

  // Category counts
  const category = lead.reporting_category || 'Unspecified';
  categoryCounts[category] = (categoryCounts[category] || 0) + 1;

  // Urgency counts
  const urgency = ['High', 'Medium', 'Low'].includes(lead.urgency)
    ? lead.urgency
    : 'Unknown';
  urgencyCounts[urgency] += 1;

  // Status counts
  const status = lead.status || 'Unknown';
  statusCounts[status] = (statusCounts[status] || 0) + 1;

  // Budget calculations
  if (typeof lead.budget === 'number' && Number.isFinite(lead.budget)) {
    numericBudgets.push(lead.budget);
  }
}

const topCategories = Object.entries(categoryCounts)
  .map(([category, lead_count]) => ({ category, lead_count }))
  .sort((a, b) => b.lead_count - a.lead_count || a.category.localeCompare(b.category))
  .slice(0, 3);

const totalPipelineBudget = numericBudgets.reduce((sum, value) => sum + value, 0);

const averageBudget = numericBudgets.length > 0
  ? Number((totalPipelineBudget / numericBudgets.length).toFixed(2))
  : null;

// Select up to five priority follow-up candidates.
// Deterministic priority: Hot first, High urgency second, known budget descending.
const tierPriority = { Hot: 3, Warm: 2, Cold: 1, null: 0 };
const urgencyPriority = { High: 3, Medium: 2, Low: 1, Unknown: 0 };

const priorityFollowUp = [...leads]
  .sort((a, b) => {
    const tierDifference = (tierPriority[b.lead_tier] || 0) - (tierPriority[a.lead_tier] || 0);
    if (tierDifference !== 0) return tierDifference;

    const urgencyDifference = (urgencyPriority[b.urgency] || 0) - (urgencyPriority[a.urgency] || 0);
    if (urgencyDifference !== 0) return urgencyDifference;

    return (b.budget || 0) - (a.budget || 0);
  })
  .slice(0, 5)
  .map(lead => ({
    lead_id: lead.lead_id,
    company: lead.company || 'Unknown company',
    lead_tier: lead.lead_tier,
    urgency: lead.urgency,
    budget: lead.budget,
    product_interest: lead.product_interest,
    notes: lead.notes,
  }));

const dataQualityNotes = [];

if (tierCounts.Unclassified > 0) {
  dataQualityNotes.push(`${tierCounts.Unclassified} valid sales lead(s) had no recognized Hot/Warm/Cold tier.`);
}

if (leads.length > numericBudgets.length) {
  dataQualityNotes.push(`${leads.length - numericBudgets.length} valid sales lead(s) had no numeric budget and were excluded from budget calculations.`);
}

return [{
  json: {
    report_type: input.report_type,
    reporting_period: input.reporting_period,
    generated_at: input.generated_at,
    source: {
      system: 'SalesGenie Google Sheets',
      rows_read: input.rows_read,
      rows_in_reporting_window: input.rows_in_reporting_window,
      included_leads: leads.length,
      excluded_spam: input.excluded_spam_count,
      excluded_support: input.excluded_support_count,
    },
    metrics: {
      total_leads: leads.length,
      lead_tier_breakdown: tierCounts,
      top_categories: topCategories,
      average_budget: averageBudget,
      total_pipeline_budget: totalPipelineBudget,
      budgeted_lead_count: numericBudgets.length,
      urgency_breakdown: urgencyCounts,
      status_breakdown: statusCounts,
    },
    priority_follow_up: priorityFollowUp,
    data_quality_notes: dataQualityNotes,
  },
}];

const lead = $('Build RAG Search Query').first().json;
const retrievedItems = $input.all();

function getValue(pageContent, label) {
  const text = String(pageContent || '').replace(/^=/, '').trim();

  const match = text.match(
    new RegExp(`^${label}:\\s*(.+)$`, 'im')
  );

  return match ? match[1].trim() : null;
}

const catalogProducts = retrievedItems
  .map((item) => {
    const result = item.json || {};

    const pageContent =
      result.document?.pageContent ||
      result.pageContent ||
      '';

    const priceText = getValue(pageContent, 'Price');

    const numericPrice = priceText
      ? Number(priceText.replace(/[^0-9.]/g, ''))
      : null;

    return {
      product_id: getValue(pageContent, 'Product ID'),
      product_name: getValue(pageContent, 'Product Name'),
      category: getValue(pageContent, 'Category'),

      price: numericPrice,
      unit_price: numericPrice,

      availability: getValue(pageContent, 'Availability'),
      description: getValue(pageContent, 'Description'),

      retrieval_score: result.score ?? null,
    };
  })
  .filter(
    (product) =>
      product.product_id &&
      product.product_name &&
      product.category &&
      Number.isFinite(product.price) &&
      product.availability
  );

const uniqueCatalogProducts = [
  ...new Map(
    catalogProducts.map((product) => [product.product_id, product])
  ).values(),
];

return [
  {
    json: {
      lead_details: {
        lead_id: lead.lead_id || null,
        customer_name: lead.customer_name || null,
        email: lead.email || null,
        company: lead.company || null,
        lead_tier: lead.classification || null,
        product_interest: lead.product_interest || null,
        total_budget: lead.budget ?? null,
        urgency: lead.urgency || null,
        notes: lead.notes || null,
      },

      catalog_version: 'pinecone-rag-v1',

      catalog_products: uniqueCatalogProducts,

      rag_metadata: {
        namespace: 'default',
        rag_query: lead.rag_query || null,
        retrieved_product_count: uniqueCatalogProducts.length,
        retrieved_product_ids: uniqueCatalogProducts.map(
          (product) => product.product_id
        ),
      },
    },
  },
];

const lead = $json;

// Get the existing trace context
const trace_context =
  lead.trace_context ||
  $('Create SalesGenie Trace Context').item.json.trace_context;

if (!trace_context || !trace_context.trace_id) {
  throw new Error('Trace context not found');
}

const queryParts = [
  `Requested product: ${lead.product_interest || 'unknown'}`,

  lead.budget !== null &&
  lead.budget !== undefined &&
  lead.budget !== ''
    ? `Budget: ${lead.budget} USD`
    : null,

  lead.urgency
    ? `Urgency: ${lead.urgency}`
    : null,

  lead.notes
    ? `Customer requirements: ${lead.notes}`
    : null
]
  .filter(Boolean)
  .join('\n');

return {
  json: {
    ...lead,

    // Add this field to the output
    trace_context,

    rag_query: queryParts,

    rag_config: {
      namespace: 'default',
      top_k: 8,
      catalog_version: 'google-sheets-phase-1'
    }
  }
};

function getField(...possibleNames) {
  for (const fieldName of possibleNames) {
    const value = $json[fieldName];

    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ''
    ) {
      return String(value).trim();
    }
  }

  return '';
}

const productId = getField(
  'product_id',
  'Product ID',
  'ProductID',
  'productId',
  'ID',
  'id'
);

const productName = getField(
  'product_name',
  'Product Name',
  'ProductName',
  'productName',
  'Name',
  'name'
);

const category = getField(
  'category',
  'Category'
);

const price = getField(
  'price',
  'Price',
  'unit_price',
  'Unit Price',
  'UnitPrice'
);

const availability = getField(
  'availability',
  'Availability',
  'stock_status',
  'Stock Status',
  'StockStatus'
);

const finish = getField(
  'finish',
  'Finish',
  'color',
  'Color',
  'colour',
  'Colour'
);

const useCase = getField(
  'use_case',
  'Use Case',
  'UseCase'
);

const features = getField(
  'features',
  'Features'
);

const warranty = getField(
  'warranty',
  'Warranty'
);

const description = getField(
  'description',
  'Description',
  'product_description',
  'Product Description'
);

const missingFields = [];

if (!productId) missingFields.push('Product ID');
if (!productName) missingFields.push('Product Name');
if (!price) missingFields.push('Price');
if (!availability) missingFields.push('Availability');

if (missingFields.length > 0) {
  throw new Error(
    `Missing required catalog fields: ${missingFields.join(', ')}. ` +
    `Available Google Sheets fields: ${Object.keys($json).join(', ')}`
  );
}

const catalogText = [
  `Product ID: ${productId}`,
  `Product Name: ${productName}`,
  `Category: ${category || 'Not specified'}`,
  `Price: ${price}`,
  `Availability: ${availability}`,
  finish ? `Finish: ${finish}` : null,
  useCase ? `Use Case: ${useCase}` : null,
  features ? `Features: ${features}` : null,
  warranty ? `Warranty: ${warranty}` : null,
  description ? `Description: ${description}` : null,
]
  .filter(Boolean)
  .join('\n');

return {
  json: {
    catalog_text: catalogText,
    product_id: productId,
    product_name: productName,
    category,
    price,
    availability,
    finish,
    use_case: useCase,
    features,
    warranty,
    description,
    catalog_version: 'google-sheets-phase-1',
  },
};

function parseRecommendation(input) {
  let value = input?.output ?? input;

  if (typeof value === 'object' && value !== null) {
    return value;
  }

  if (typeof value !== 'string') {
    throw new Error(
      'Product Recommender output is missing. Connect this Code node directly after Product Recommender Agent.'
    );
  }

  let cleanValue = value
    .replace(/\u00A0/g, ' ')
    .replace(/\u202F/g, ' ')
    .replace(/^\uFEFF/, '')
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '');

  const firstBrace = cleanValue.indexOf('{');
  const lastBrace = cleanValue.lastIndexOf('}');

  if (firstBrace === -1 || lastBrace === -1) {
    throw new Error(
      `Product Recommender output does not contain complete JSON. Received: ${cleanValue.slice(0, 300)}`
    );
  }

  cleanValue = cleanValue.slice(firstBrace, lastBrace + 1);

  try {
    return JSON.parse(cleanValue);
  } catch (error) {
    throw new Error(
      `Product Recommender JSON cannot be parsed: ${error.message}. Received: ${cleanValue.slice(0, 300)}`
    );
  }
}

function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

// Read the Product Recommender output from the direct input
const recommendation = parseRecommendation($json);

// Read lead data from your RAG formatter node
const formatterData = $('Format Retrieved Catalog Context').first().json;
const lead = formatterData.lead_details || {};

// Validate recommendation result
const products = Array.isArray(recommendation.recommendations)
  ? recommendation.recommendations
  : [];

if (
  recommendation.recommendation_status !== 'recommendations_found' ||
  products.length === 0
) {
  throw new Error(
    `Cannot create approval request because no recommendations were found. Status: ${
      recommendation.recommendation_status || 'missing'
    }`
  );
}

if (!lead.email) {
  throw new Error(
    'Cannot create approval request because the customer email is missing.'
  );
}

// Create short product summary for Google Sheets
const productNames = products
  .map((product) => {
    const name = product.product_name || 'Unnamed product';
    const price = product.unit_price ?? 'Price unavailable';

    return `${name} — $${price}`;
  })
  .join(', ');

// Create formatted HTML cards for the customer email
const productHtml = products
  .map((product, index) => {
    const name = escapeHtml(product.product_name || 'Unnamed product');
    const price = escapeHtml(product.unit_price ?? 'Price unavailable');
    const availability = escapeHtml(
      product.availability || 'Availability not confirmed'
    );
    const rationale = escapeHtml(product.rationale || '');

    const limitations =
      Array.isArray(product.limitations) && product.limitations.length > 0
        ? `
          <p style="margin:10px 0 0;color:#8a5b00;font-size:14px;line-height:1.5;">
            <strong>Note:</strong> ${escapeHtml(product.limitations.join(' '))}
          </p>
        `
        : '';

    return `
      <div style="margin:0 0 18px;padding:16px;border:1px solid #d9e1df;border-radius:8px;background:#ffffff;">
        <div style="font-size:17px;font-weight:700;color:#1f2937;line-height:1.4;">
          ${index + 1}. ${name}
        </div>

        <div style="margin:7px 0 10px;font-size:15px;font-weight:700;color:#1f4b45;">
          $${price}
          <span style="color:#15803d;font-weight:600;">(${availability})</span>
        </div>

        <div style="font-size:15px;color:#374151;line-height:1.55;">
          ${rationale}
        </div>

        ${limitations}
      </div>
    `;
  })
  .join('');

// Date and email details
const now = new Date();

const draftSubject = 'Standing Desk Options from Oak & Ember Interiors';

const customerName = escapeHtml(lead.customer_name || 'there');

const customerMessage = escapeHtml(
  recommendation.customer_message ||
    'We selected product options based on your request.'
);

// Create formatted HTML email body
const draftBody = `
<!DOCTYPE html>
<html>
  <body style="margin:0;padding:0;background:#f4f6f5;font-family:Arial,Helvetica,sans-serif;color:#1f2937;">
    <div style="max-width:680px;margin:0 auto;padding:28px 16px;">

      <div style="padding:24px 28px;background:#1f4b45;border-radius:10px 10px 0 0;">
        <div style="font-size:23px;font-weight:700;color:#ffffff;">
          Oak &amp; Ember Interiors
        </div>
        <div style="margin-top:5px;font-size:14px;color:#d8eee7;">
          Product recommendations for your workspace
        </div>
      </div>

      <div style="padding:30px 28px;background:#ffffff;border:1px solid #d9e1df;border-top:none;border-radius:0 0 10px 10px;">

        <p style="margin:0 0 18px;font-size:16px;line-height:1.55;">
          Hi ${customerName},
        </p>

        <p style="margin:0 0 22px;font-size:16px;line-height:1.55;color:#374151;">
          ${customerMessage}
        </p>

        ${productHtml}

        <p style="margin:24px 0 0;font-size:16px;line-height:1.55;color:#374151;">
          Please let us know if you would like more details about any of these options.
        </p>

        <p style="margin:25px 0 0;font-size:16px;line-height:1.55;color:#374151;">
          Best regards,<br />
          <strong>Oak &amp; Ember Interiors</strong>
        </p>

      </div>
    </div>
  </body>
</html>
`;

return {
  json: {
    approval_id: `APR-${now.getTime()}-${lead.lead_id || 'UNKNOWN'}`,

    lead_id: lead.lead_id || null,
    lead_tier: lead.lead_tier || null,

    customer_name: lead.customer_name || null,
    customer_email: lead.email,

    recommended_product_names: productNames,

    draft_subject: draftSubject,
    draft_body: draftBody,

    approval_status: 'Pending',

    reviewer_name: null,
    reviewed_at: null,
    sent_at: null,
  },
};

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

function randomHex(length) {
  const chars = '0123456789abcdef';
  let value = '';

  for (let i = 0; i < length; i++) {
    value += chars[Math.floor(Math.random() * chars.length)];
  }

  return value;
}

// Use the exact name of your query node
const source = $('Build RAG Search Query').first().json;

// All Pinecone output items
const inputItems = $input.all();

const trace = source.trace_context;

if (!trace || !trace.trace_id) {
  throw new Error('Missing trace_context');
}

// Create one span for this Pinecone retrieval operation
const pineconeSpanId = randomHex(16);

const parentSpanId =
  trace.current_span_id || trace.root_span_id;

const startTimeUnixNano =
  source.pinecone_observation?.start_time_unix_nano ||
  `${Date.now()}000000`;

const endTimeUnixNano = `${Date.now()}000000`;

// Convert Pinecone output into product records
const rawProducts = inputItems.map(item => {
  const data = item.json;

  const metadata =
    data.metadata ||
    data.document?.metadata ||
    {};

  const text = String(
    data.pageContent ||
    data.document?.pageContent ||
    data.text ||
    data.document?.text ||
    metadata.text ||
    ''
  );

  function extract(label) {
    const pattern = new RegExp(
      `${label}:\\s*([^\\n\\r]+)`,
      'i'
    );

    return text.match(pattern)?.[1]?.trim() || null;
  }

  const productId =
    extract('Product ID') ||
    data.id ||
    metadata.product_id ||
    null;

  const productName =
    extract('Product Name') ||
    metadata.product_name ||
    null;

  const category =
    extract('Category') ||
    metadata.category ||
    null;

  const price =
    extract('Price') ||
    metadata.price ||
    null;

  const availability =
    extract('Availability') ||
    metadata.availability ||
    null;

  const description =
    extract('Description') ||
    metadata.description ||
    null;

  return {
    product_id: productId,
    product_name: productName,
    category,
    price,
    availability,
    description,
    score: data.score ?? data.similarity ?? null
  };
});

// Remove duplicate products while keeping the highest score
const uniqueProducts = [];

for (const product of rawProducts) {
  const existing = uniqueProducts.find(
    item => item.product_id === product.product_id
  );

  if (!existing) {
    uniqueProducts.push(product);
  } else {
    const existingScore = Number(existing.score || 0);
    const newScore = Number(product.score || 0);

    if (newScore > existingScore) {
      Object.assign(existing, product);
    }
  }
}

const productIds = uniqueProducts.map(
  product => product.product_id
);

const scores = rawProducts.map(
  product => product.score
);

const inputSummary = {
  product_interest: source.product_interest || null,
  budget: source.budget ?? null,
  urgency: source.urgency || null,
  query: source.rag_query || null,
  namespace: source.rag_config?.namespace || 'default',
  top_k: source.rag_config?.top_k || 8
};

const outputSummary = {
  raw_result_count: rawProducts.length,
  unique_product_count: uniqueProducts.length,
  product_ids: productIds,
  scores,
  status: uniqueProducts.length > 0
    ? 'success'
    : 'no_results'
};

const otelPayload = {
  resourceSpans: [
    {
      resource: {
        attributes: [
          {
            key: 'service.name',
            value: {
              stringValue: 'salesgenie-rag'
            }
          },
          {
            key: 'deployment.environment.name',
            value: {
              stringValue: trace.environment || 'development'
            }
          }
        ]
      },

      scopeSpans: [
        {
          scope: {
            name: 'salesgenie.rag',
            version: '1.0.0'
          },

          spans: [
            {
              traceId: trace.trace_id,
              spanId: pineconeSpanId,
              parentSpanId: parentSpanId,
              name: 'pinecone.retrieve_products',
              kind: 3,
              startTimeUnixNano,
              endTimeUnixNano,

              status: {
                code: 1
              },

              attributes: [
                {
                  key: 'langfuse.trace.name',
                  value: {
                    stringValue:
                      trace.trace_name ||
                      'salesgenie.email.process'
                  }
                },
                {
                  key: 'langfuse.observation.type',
                  value: {
                    stringValue: 'retriever'
                  }
                },
                {
                  key: 'langfuse.observation.input',
                  value: {
                    stringValue: JSON.stringify(inputSummary)
                  }
                },
                {
                  key: 'langfuse.observation.output',
                  value: {
                    stringValue: JSON.stringify(outputSummary)
                  }
                },
                {
                  key: 'salesgenie.workflow.name',
                  value: {
                    stringValue: 'salesgenie.rag'
                  }
                },
                {
                  key: 'salesgenie.agent.name',
                  value: {
                    stringValue: 'pinecone_retrieval'
                  }
                },
                {
                  key: 'salesgenie.retrieval.result_count',
                  value: {
                    stringValue: String(rawProducts.length)
                  }
                },
                {
                  key: 'salesgenie.retrieval.unique_product_count',
                  value: {
                    stringValue: String(uniqueProducts.length)
                  }
                },
                {
                  key: 'salesgenie.retrieval.product_ids',
                  value: {
                    stringValue: JSON.stringify(productIds)
                  }
                },
                {
                  key: 'salesgenie.retrieval.scores',
                  value: {
                    stringValue: JSON.stringify(scores)
                  }
                },
                {
                  key: 'salesgenie.retrieval.namespace',
                  value: {
                    stringValue:
                      source.rag_config?.namespace ||
                      'default'
                  }
                },
                {
                  key: 'salesgenie.catalog.version',
                  value: {
                    stringValue:
                      source.rag_config?.catalog_version ||
                      trace.catalog_version ||
                      'unknown'
                  }
                }
              ]
            }
          ]
        }
      ]
    }
  ]
};

return [
  {
    json: {
      ...source,

      retrieved_products: uniqueProducts,

      retrieval_summary: outputSummary,

      trace_context: {
        ...trace,
        current_span_id: pineconeSpanId
      },

      otel_payload: otelPayload
    }
  }
];

function randomHex(length) {
  const chars = '0123456789abcdef';
  let value = '';
  for (let i = 0; i < length; i++) {
    value += chars[Math.floor(Math.random() * chars.length)];
  }
  return value;
}

const agentOutput = $json;

// Always recover upstream RAG context as well as trace context.
const ragSource = $('Build RAG Search Query').first().json;
const source = {
  ...ragSource,
  ...agentOutput,
  trace_context:
    agentOutput.trace_context || ragSource.trace_context
};

const trace = source.trace_context;

if (!trace?.trace_id || !/^[0-9a-f]{32}$/i.test(trace.trace_id)) {
  throw new Error('Missing or invalid 32-character trace ID');
}

const parentSpanId = trace.current_span_id || trace.root_span_id;

if (!parentSpanId || !/^[0-9a-f]{16}$/i.test(parentSpanId)) {
  throw new Error('Missing or invalid parent span ID');
}

const recommendationSpanId = randomHex(16);
const startTimeUnixNano = (BigInt(Date.now()) * 1000000n).toString();

// Extract the recommendation output.
let recommendation =
  agentOutput.output ??
  agentOutput.text ??
  agentOutput.response ??
  agentOutput.result ??
  agentOutput;

if (typeof recommendation === 'string') {
  try {
    recommendation = JSON.parse(recommendation);
  } catch {
    recommendation = { text: recommendation };
  }
}

// Preserve available RAG context for the span input.
const recommendationInput = {
  product_interest: source.product_interest ?? null,
  budget: source.budget ?? null,
  urgency: source.urgency ?? null,
  rag_query: source.rag_query ?? null,
  retrieved_products: source.retrieved_products ?? [],
  product_context: source.product_context ?? null
};

// Allow a measurable span duration.
const endTimeUnixNano =
  (BigInt(Date.now()) * 1000000n).toString();

const attributes = [
  {
    key: 'langfuse.observation.type',
    value: { stringValue: 'generation' }
  },
  {
    key: 'langfuse.observation.input',
    value: { stringValue: JSON.stringify(recommendationInput) }
  },
  {
    key: 'langfuse.observation.output',
    value: { stringValue: JSON.stringify(recommendation) }
  },
  {
    key: 'langfuse.observation.model.name',
    value: { stringValue: 'gpt-4o-mini' }
  },
  {
    key: 'salesgenie.workflow.name',
    value: { stringValue: 'salesgenie.product_recommendation' }
  },
  {
    key: 'salesgenie.agent.name',
    value: { stringValue: 'product_recommendation' }
  }
];

const usage =
  agentOutput.usage ||
  agentOutput.token_usage ||
  agentOutput.tokenUsage;

if (usage) {
  const inputTokens =
    usage.input_tokens ?? usage.prompt_tokens ?? usage.inputTokens;
  const outputTokens =
    usage.output_tokens ?? usage.completion_tokens ?? usage.outputTokens;

  if (inputTokens != null) {
    attributes.push({
      key: 'gen_ai.usage.input_tokens',
      value: { intValue: Number(inputTokens) }
    });
  }

  if (outputTokens != null) {
    attributes.push({
      key: 'gen_ai.usage.output_tokens',
      value: { intValue: Number(outputTokens) }
    });
  }
}

const otelPayload = {
  resourceSpans: [{
    resource: {
      attributes: [{
        key: 'service.name',
        value: { stringValue: 'salesgenie-recommendation' }
      }]
    },
    scopeSpans: [{
      scope: {
        name: 'salesgenie.recommendation',
        version: '1.0.0'
      },
      spans: [{
        traceId: trace.trace_id,
        spanId: recommendationSpanId,
        parentSpanId,
        name: 'product.recommendation',
        kind: 1,
        startTimeUnixNano,
        endTimeUnixNano,
        status: { code: 1 },
        attributes
      }]
    }]
  }]
};

return {
  json: {
    ...source,
    recommendation_result: recommendation,
    trace_context: {
      ...trace,
      current_span_id: recommendationSpanId
    },
    otel_payload: otelPayload
  }
};

